class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        window = 0
        for i in range(k):                      # first window, no slice copy
            window += nums[i]
        best = window
        for i in range(k, len(nums)):
            window += nums[i] - nums[i - k]     # slide: add the new element, drop the old
            best = max(best, window)
        return best / k
